import React, { useState, useEffect, useRef } from 'react';

// --- Configuration ---
const API_URL = 'http://127.0.0.1:8000'; // Your FastAPI backend URL

// --- Style Definitions (CSS-in-JS) ---
const colors = {
    primary: '#10b981', 
    primaryHover: '#059669',
    primaryDisabled: '#6ee7b7',
    lightGray: '#f3f4f6', 
    mediumGray: '#e5e7eb',
    darkGray: '#4b5563',
    textPrimary: '#1f2937', // Dark color for text
    white: '#ffffff',
};

const styles = {
    appContainer: { backgroundColor: colors.lightGray, minHeight: '100vh', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column' },
    header: { backgroundColor: colors.white, padding: '1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)' },
    logoContainer: { display: 'flex', alignItems: 'center', gap: '0.5rem' },
    headerTitle: { fontSize: '1.5rem', fontWeight: 'bold', color: colors.textPrimary },
    nav: { display: 'flex', alignItems: 'center', gap: '1rem' },
    navButton: { padding: '0.5rem 0.75rem', borderRadius: '0.375rem', fontSize: '0.875rem', fontWeight: '500', border: 'none', cursor: 'pointer', transition: 'background-color 0.2s' },
    mainContent: { flexGrow: 1, padding: '2rem', display: 'flex', alignItems: 'center', justifyContent: 'center' },
    contentWrapper: { width: '100%', maxWidth: '56rem', height: '100%' },
    card: { backgroundColor: colors.white, padding: '2rem', borderRadius: '0.75rem', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)' },
    button: { width: '100%', display: 'flex', justifyContent: 'center', padding: '0.5rem 1rem', border: 'none', borderRadius: '0.375rem', boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)', fontSize: '0.875rem', fontWeight: '500', color: colors.white, backgroundColor: colors.primary, cursor: 'pointer', transition: 'background-color 0.2s' },
    // --- FIX IS HERE ---
    input: { 
        marginTop: '0.25rem', 
        display: 'block', 
        width: '100%', 
        padding: '0.5rem 0.75rem', 
        backgroundColor: colors.white, 
        color: colors.textPrimary, // Explicitly set text color to be visible
        border: '1px solid #d1d5db', 
        borderRadius: '0.375rem', 
        boxSizing: 'border-box' 
    },
    chatContainer: { display: 'flex', flexDirection: 'column', height: '80vh' },
    messagesContainer: { flexGrow: 1, padding: '1.5rem', overflowY: 'auto' },
    messageBubbleUser: { maxWidth: '80%', padding: '0.5rem 1rem', borderRadius: '0.75rem', backgroundColor: colors.primary, color: colors.white, alignSelf: 'flex-end', marginBottom: '1rem' },
    messageBubbleBot: { maxWidth: '80%', padding: '0.5rem 1rem', borderRadius: '0.75rem', backgroundColor: colors.mediumGray, color: colors.textPrimary, alignSelf: 'flex-start', marginBottom: '1rem' },
    chatForm: { padding: '1rem', borderTop: `1px solid ${colors.mediumGray}`, display: 'flex', gap: '0.5rem' },
};

// Custom hook for hover effects
const useHover = () => {
    const [hovered, setHovered] = useState(false);
    const eventHandlers = { onMouseEnter: () => setHovered(true), onMouseLeave: () => setHovered(false) };
    return [hovered, eventHandlers];
};

// --- Main App Component ---
function App() {
    const [userId, setUserId] = useState(null);
    const [page, setPage] = useState('chat');
    const [jsPDF, setJsPDF] = useState(null);

    useEffect(() => {
        let sessionUserId = localStorage.getItem('symptomSageUserId');
        if (!sessionUserId) {
            sessionUserId = crypto.randomUUID();
            localStorage.setItem('symptomSageUserId', sessionUserId);
        }
        setUserId(sessionUserId);
        // Load jspdf from window object
        if (window.jspdf) {
            setJsPDF(() => window.jspdf.jsPDF);
        }
    }, []);

    const [chatHover, chatHandlers] = useHover();
    const [dashHover, dashHandlers] = useHover();

    const renderPage = () => {
        if (!userId) {
            return <div style={styles.card}><p>Initializing session...</p></div>;
        }
        switch (page) {
            case 'chat': return <ChatPage userId={userId} />;
            case 'dashboard': return <DashboardPage userId={userId} jsPDF={jsPDF} />;
            default: return <ChatPage userId={userId} />;
        }
    };
    
    return (
        <div style={styles.appContainer}>
            <header style={styles.header}>
                <div style={styles.logoContainer}>
                    <svg xmlns="http://www.w3.org/2000/svg" style={{height: '2rem', width: '2rem', color: colors.primary}} viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                    </svg>
                    <h1 style={styles.headerTitle}>SymptomSage</h1>
                </div>
                <nav style={styles.nav}>
                    <button onClick={() => setPage('chat')} style={{ ...styles.navButton, backgroundColor: page === 'chat' ? '#d1fae5' : (chatHover ? colors.mediumGray : colors.white), color: page === 'chat' ? '#065f46' : colors.darkGray }} {...chatHandlers}>Chat</button>
                    <button onClick={() => setPage('dashboard')} style={{ ...styles.navButton, backgroundColor: page === 'dashboard' ? '#d1fae5' : (dashHover ? colors.mediumGray : colors.white), color: page === 'dashboard' ? '#065f46' : colors.darkGray }} {...dashHandlers}>Dashboard</button>
                </nav>
            </header>
            <main style={styles.mainContent}>
                <div style={styles.contentWrapper}>
                    {renderPage()}
                </div>
            </main>
        </div>
    );
}

// --- Chat Page ---
function ChatPage({ userId }) {
    const [messages, setMessages] = useState([]);
    const [input, setInput] = useState('');
    const [loading, setLoading] = useState(true);
    const messagesEndRef = useRef(null);
    const [sendBtnHover, sendBtnHandlers] = useHover();

    const scrollToBottom = () => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }) };

    useEffect(scrollToBottom, [messages]);
    
    useEffect(() => {
        const fetchHistory = async () => {
            if (!userId) return;
            try {
                const response = await fetch(`${API_URL}/history`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_id: userId }) });
                if (response.ok) setMessages(await response.json());
            } catch (error) {
                console.error("Failed to fetch history:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchHistory();
    }, [userId]);

    const handleSend = async (e) => {
        e.preventDefault();
        if (!input.trim() || !userId) return;

        const userMessage = { role: 'user', content: input, timestamp: new Date().toISOString() };
        setMessages(prev => [...prev, userMessage]);
        const currentInput = input;
        setInput('');
        setLoading(true);
        
        try {
            const response = await fetch(`${API_URL}/chat`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_id: userId, message: currentInput }) });
            if (!response.ok) throw new Error('Failed to get response.');
            const botMessage = await response.json();
            setMessages(prev => [...prev, botMessage]);
        } catch (error) {
            console.error("Chat error:", error);
            setMessages(prev => [...prev, { role: 'bot', content: 'Sorry, I couldn\'t connect. Please try again.', timestamp: new Date().toISOString() }]);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div style={{...styles.card, ...styles.chatContainer, padding: 0}}>
            <div style={styles.messagesContainer}>
                <div style={{display: 'flex', flexDirection: 'column'}}>
                    {messages.map((msg, index) => (<div key={index} style={msg.role === 'user' ? styles.messageBubbleUser : styles.messageBubbleBot}><p>{msg.content}</p></div>))}
                    <div ref={messagesEndRef} />
                </div>
            </div>
             <div style={styles.chatForm}>
                <input 
                    type="text" 
                    value={input} 
                    onChange={(e) => setInput(e.target.value)} 
                    placeholder="Describe your symptoms..." 
                    style={{
                        ...styles.input, 
                        flexGrow: 1, 
                        borderRadius: '9999px',
                        // --- IMPROVEMENT IS HERE ---
                        backgroundColor: loading ? colors.lightGray : colors.white // Visually show when disabled
                    }} 
                    disabled={loading} 
                    onKeyPress={(e) => e.key === 'Enter' && !loading && handleSend(e)} 
                />
                <button onClick={handleSend} disabled={loading} style={{...styles.button, width: 'auto', borderRadius: '9999px', padding: '0.5rem', backgroundColor: loading ? colors.primaryDisabled : (sendBtnHover ? colors.primaryHover : colors.primary)}} {...sendBtnHandlers}>
                     <svg xmlns="http://www.w3.org/2000/svg" style={{height: '1.5rem', width: '1.5rem'}} viewBox="0 0 24 24" fill="none" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
            </div>
            <p style={{fontSize: '0.75rem', color: '#6b7280', padding: '0 1rem 0.5rem', textAlign: 'center'}}>Disclaimer: SymptomSage is an AI assistant and does not provide medical advice.</p>
        </div>
    );
}

// --- Dashboard Page ---
function DashboardPage({ userId, jsPDF }) {
    const [history, setHistory] = useState([]);
    const [loading, setLoading] = useState(true);
    const [exportHover, exportHandlers] = useHover();
    
    useEffect(() => {
        const fetchHistory = async () => {
            if (!userId) return;
            try {
                const response = await fetch(`${API_URL}/history`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_id: userId }) });
                if (response.ok) setHistory(await response.json());
            } catch (error) {
                console.error("Failed to fetch history:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchHistory();
    }, [userId]);

    const handleExportPDF = () => {
        if (!jsPDF) {
            alert("PDF library is not loaded yet. Please try again in a moment.");
            return;
        }
        const doc = new jsPDF();
        doc.setFontSize(18);
        doc.text("SymptomSage Health Log", 14, 22);
        doc.setFontSize(11);
        doc.setTextColor(100);

        let y = 40;
        history.forEach(msg => {
            if (y > 280) { doc.addPage(); y = 20; }
            const text = `${msg.role.toUpperCase()} (${new Date(msg.timestamp).toLocaleString()}):\n${msg.content}`;
            const splitText = doc.splitTextToSize(text, 180);
            doc.text(splitText, 14, y);
            y += (splitText.length * 5) + 5;
        });
        
        doc.save("symptomsage_log.pdf");
    };

    if (loading) return <div style={styles.card}><p>Loading history...</p></div>;

    return (
        <div style={{...styles.card, height: '80vh', display: 'flex', flexDirection: 'column'}}>
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem'}}>
                 <h2 style={{fontSize: '1.5rem', fontWeight: 'bold', color: colors.textPrimary}}>Health Dashboard</h2>
                 <button onClick={handleExportPDF} style={{...styles.button, width: 'auto', backgroundColor: exportHover ? colors.primaryHover : colors.primary}} {...exportHandlers}>Export as PDF</button>
            </div>
            <div style={{flexGrow: 1, overflowY: 'auto', borderTop: `1px solid ${colors.mediumGray}`, paddingTop: '1rem'}}>
                 {history.length === 0 ? (<p>No history found. Start a conversation in the chat tab!</p>) : (
                    <div style={{display: 'flex', flexDirection: 'column', gap: '1rem'}}>
                        {history.map((msg, index) => (
                             <div key={index} style={{padding: '0.75rem', borderRadius: '0.5rem', backgroundColor: colors.lightGray, border: `1px solid ${colors.mediumGray}`}}>
                                <p style={{fontWeight: 'bold', color: msg.role === 'user' ? colors.primary : '#3b82f6'}}>{msg.role === 'user' ? 'You' : 'SymptomSage'}</p>
                                <p style={{color: colors.textPrimary}}>{msg.content}</p>
                                <p style={{fontSize: '0.75rem', color: colors.darkGray, marginTop: '0.25rem'}}>{new Date(msg.timestamp).toLocaleString()}</p>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

export default App;
